 "content": "def transform(grid):
    """Fill each 5-bordered chamber and project its top opening leftward."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            # Connected components of the outline color.
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            # The motif is a rectangular chamber with a one-cell gap in its top edge.
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            missing = [(r0,x) for x in range(c0+1,c1) if grid[r0][x] != 5]
            if len(missing) != 1:
                continue
            gap_r, gap_c = missing[0]
            if any(grid[y][c0] != 5 or grid[y][c1] != 5 for y in range(r0,r1+1)):
                continue
            if any(grid[r1][x] != 5 for x in range(c0,c1+1)):
                continue
            # The chamber interior and aperture become color 2.
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    out[y][x] = 2
            out[gap_r][gap_c] = 2
            # The aperture emits a leftward horizontal beam one row above the frame.
            if gap_r > 0:
                for x in range(gap_c+1):
                    if grid[gap_r-1][x] == 0:
                        out[gap_r-1][x] = 2
    return out
